window.kbPageData["views/entry/k-ef5dd52a8b2095c8"] = {"key":"entry/k-ef5dd52a8b2095c8","state":{"route":"entry/k-ef5dd52a8b2095c8"},"node":{"id":"k-ef5dd52a8b2095c8","mode":"k","title":"全国卫生与健康大会（10 月 12—13 日）","type":"事实与事件","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment","modern"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["社会治理"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"全国卫生与健康大会（10 月 12—13 日）","slug":"2c8d737ea308"}],"directorySummary":"考点四十 全国卫生与健康大会（10 月 12—13 日）\n10 月 12 日至 13 日，全国卫生与健康大会在北京召开，讲话强调，“十五五”时期是实现到\n2035 年建成健康中国目标的关键时期，要坚定不移走中国特色卫生与健康发展道路，贯彻新\n时代卫生与健康工作方针，扬优势、固基础、补短板、强弱项，推…","sources":[{"id":"628277e2a7bd9720","label":"全国卫生与健康大会（10 月 12—13 日）","topic":"重要会议讲话","category":"时政","text":"考点四十 全国卫生与健康大会（10 月 12—13 日）\n10 月 12 日至 13 日，全国卫生与健康大会在北京召开，讲话强调，“十五五”时期是实现到\n2035 年建成健康中国目标的关键时期，要坚定不移走中国特色卫生与健康发展道路，贯彻新\n时代卫生与健康工作方针，扬优势、固基础、补短板、强弱项，推动卫生与健康事业高质量发\n展，确保健康中国建设取得决定性进展。\n讲话指出，我们要建成的健康中国，是均衡普惠、优质高效的健康中国，应当具有强大的健康\n管理能力、疾病防控能力、医疗服务能力、医保支撑能力、医药创新能力、人才培养能力。必\n须坚定实施健康优先发展战略；预防是最经济最有效的健康策略；全面提高医疗服务水平是建\n成健康中国的重点任务；坚持把推进医疗、医保、医药协同发展和治理作为医药卫生体制改革\n的主攻方向；保障人民健康需要建强卫生与健康系统干部人才队伍；积极推动构建人类卫生健\n康共同体。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":9,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-ef5dd52a8b2095c8":[]}};
